const watches={azur:{id:2,name:"Montre Ligne Azur",tagline:"Le temps en clair.",image:"/assets/watch-azure.webp",price:149,old:179,accent:"#3d86ff",surface:"#0a2449",note:"ACIER BROSSÉ / CADRAN BLEU",description:"Acier brossé, cadran bleu nuit et proportions nettes : une montre précise et équilibrée, dessinée pour chaque jour.",specs:[["Boîtier","Acier · 38 mm"],["Bracelet","Acier brossé"],["Verre","Minéral renforcé"],["Étanchéité","5 ATM"]]},emeraude:{id:7,name:"Montre Ligne Émeraude",tagline:"L’élégance juste.",image:"/assets/watch-emerald.webp",price:169,old:199,accent:"#efb879",surface:"#12382b",note:"OR ROSE / CADRAN ÉMERAUDE",description:"Cadran vert profond, boîtier or rose et bracelet en cuir brun pour une présence chaleureuse sans excès.",specs:[["Boîtier","Acier or rose · 38 mm"],["Bracelet","Cuir brun"],["Verre","Minéral renforcé"],["Étanchéité","5 ATM"]]},minuit:{id:8,name:"Montre Ligne Minuit",tagline:"Le caractère net.",image:"/assets/watch-burgundy.webp",price:159,old:189,accent:"#ff758e",surface:"#3b111d",note:"ACIER NOIR / CADRAN BORDEAUX",description:"Acier noir, cuir grainé et cadran bordeaux composent une silhouette affirmée qui garde toute la sobriété de la Ligne.",specs:[["Boîtier","Acier noir · 38 mm"],["Bracelet","Cuir noir grainé"],["Verre","Minéral renforcé"],["Étanchéité","5 ATM"]]}};
const slug=new URLSearchParams(location.search).get("watch")||location.pathname.split("/").filter(Boolean).pop();const watch=watches[slug]||watches.azur;const euro=new Intl.NumberFormat("fr-FR",{style:"currency",currency:"EUR",maximumFractionDigits:0});const $=s=>document.querySelector(s);document.title=`${watch.name} — FOLKI`;document.documentElement.style.setProperty("--watch-accent",watch.accent);document.documentElement.style.setProperty("--watch-surface",watch.surface);$("#watch-name").textContent=watch.name;$("#watch-tagline").textContent=watch.tagline;$("#watch-description").textContent=watch.description;$("#watch-image").src=watch.image;$("#watch-image").alt=watch.name;$("#watch-note").textContent=watch.note;$("#watch-price").textContent=euro.format(watch.price);$("#watch-old-price").textContent=euro.format(watch.old);$("#watch-specs").innerHTML=watch.specs.map(([a,b])=>`<div><dt>${a}</dt><dd>${b}</dd></div>`).join("");$(`[data-variant="${slug}"]`)?.classList.add("active");
const readCart=()=>{try{const c=JSON.parse(localStorage.getItem("folki-cart")||"[]");return Array.isArray(c)?c:[]}catch{return[]}};const update=()=>$("#watch-count").textContent=readCart().reduce((n,x)=>n+Number(x.qty||0),0);$("#watch-add").addEventListener("click",e=>{const c=readCart(),line=c.find(x=>x.id===watch.id);line?line.qty++:c.push({id:watch.id,qty:1});localStorage.setItem("folki-cart",JSON.stringify(c));update();e.currentTarget.classList.add("added");e.currentTarget.innerHTML="Ajoutée au panier <span>✓</span>";$("#watch-go-cart").classList.add("visible")});update();
